<?php
namespace Core;class SourceRegion{protected static $mapFile='';protected static $hitFile='';protected static $cfgFile='';public static function init(string $a):void{self::$mapFile=rtrim($a,'/').'/source_region_map.json';self::$hitFile=rtrim($a,'/').'/source_region_hits.json';self::$cfgFile=rtrim($a,'/').'/source_config.json';}public static function loadSourceConfig():array{if(!is_file(self::$cfgFile)){return['origin'=>''];}$a=json_decode(@file_get_contents(self::$cfgFile),true);return is_array($a)?$a:['origin'=>''];}public static function saveSourceConfig(string $a):void{$b=dirname(self::$cfgFile);if(!is_dir($b)){@mkdir($b,0750,true);}@file_put_contents(self::$cfgFile,json_encode(['origin'=>$a,'updated_at'=>time()],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT));}public static function loadRegionMap():array{if(!is_file(self::$mapFile)){return[];}$a=json_decode(@file_get_contents(self::$mapFile),true);return is_array($a)?$a:[];}public static function saveRegionMap(array $a):void{$b=dirname(self::$mapFile);if(!is_dir($b)){@mkdir($b,0750,true);}@file_put_contents(self::$mapFile,json_encode($a,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT));}public static function setRegionOrigin(string $a,string $b):void{$c=self::loadRegionMap();$c[$a]=$b;self::saveRegionMap($c);}public static function removeRegionOrigin(string $a):void{$b=self::loadRegionMap();unset($b[$a]);self::saveRegionMap($b);}public static function getRegionOrigin(string $a):?string{$b=self::loadRegionMap();return $b[$a]??null;}public static function recordHit(string $a,string $b):void{$c=self::loadHits();$c[]=['region'=>$a,'ip'=>$b,'time'=>time(),'time_str'=>date('Y-m-d H:i:s')];if(count($c)>200){$c=array_slice($c,-200);}self::saveHits($c);}public static function loadHits():array{if(!is_file(self::$hitFile)){return[];}$a=json_decode(@file_get_contents(self::$hitFile),true);return is_array($a)?$a:[];}protected static function saveHits(array $a):void{$b=dirname(self::$hitFile);if(!is_dir($b)){@mkdir($b,0750,true);}@file_put_contents(self::$hitFile,json_encode($a,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT));}public static function getClientIp():string{$a=['HTTP_CLIENT_IP','HTTP_X_FORWARDED_FOR','HTTP_X_FORWARDED','HTTP_X_CLUSTER_CLIENT_IP','HTTP_FORWARDED_FOR','HTTP_FORWARDED','REMOTE_ADDR',];foreach($a as $b){if(isset($_SERVER[$b])&&$_SERVER[$b]!==''){$c=$_SERVER[$b];if(strpos($c,',')!==false){$c=trim(explode(',',$c)[0]);}if(self::isValidIp($c)){return $c;}}}return'0.0.0.0';}protected static function isValidIp(string $a):bool{if($a==='0.0.0.0'||$a==='::1'||$a==='localhost'){return false;}return filter_var($a,FILTER_VALIDATE_IP)!==false;}protected static function isLocalIp(string $a):bool{if($a==='127.0.0.1'||$a==='::1'){return true;}if(strpos($a,'192.168.')===0||strpos($a,'10.')===0||strpos($a,'172.')===0){return true;}return false;}public static function detectRegion(string $a):string{if(self::isLocalIp($a)){return'本地';}return self::queryIpApi($a);}protected static function queryIpApi(string $a):string{$b='http://ip-api.com/json/'.urlencode($a).'?lang=zh-CN';$c=curl_init();curl_setopt($c,CURLOPT_URL,$b);curl_setopt($c,CURLOPT_RETURNTRANSFER,true);curl_setopt($c,CURLOPT_TIMEOUT,5);curl_setopt($c,CURLOPT_USERAGENT,'MediaLibrary-SourceRegion/1.0');$d=curl_exec($c);if($d===false){@curl_close($c);return'';}$e=(int)curl_getinfo($c,CURLINFO_HTTP_CODE);@curl_close($c);if($e!==200){return'';}$f=json_decode($d,true);if(!is_array($f)||($f['status']??'')!=='success'){return'';}$g=array_filter([$f['country']??'',$f['regionName']??'',$f['city']??'',]);return implode(' ',$g);}}